SELECT COUNT(DISTINCT bill_id) AS distinct_bills_may
FROM store.pos_lines
WHERE bill_ts >= '2026-05-04' AND bill_ts < '2026-06-01';

SELECT sku, name, gtin
FROM store.products
WHERE name ILIKE '%toned%milk%' OR name ILIKE '%milk%toned%';

SELECT sku, gtin, name, pack, case_units, case_kg, flow
FROM store.products
WHERE name ILIKE '%atta%' OR name ILIKE '%wheat%';

SELECT DISTINCT order_id
FROM warehouse.shipping_notice_lines
LIMIT 20;

SELECT COUNT(*) as pallet_count
FROM warehouse.shipments
WHERE arrived_ts >= '2026-06-01' AND arrived_ts < '2026-07-01';

SELECT COUNT(DISTINCT date) as days_with_writeoffs
FROM store.write_offs
WHERE date >= '2026-06-01' AND date <= '2026-06-30';

SELECT COUNT(*) as gr_lines
FROM store.goods_receipts
WHERE received_ts >= '2026-06-01' AND received_ts < '2026-07-01';

SELECT table_schema, table_name
FROM information_schema.tables
WHERE table_name LIKE '%customer%';

SELECT COUNT(*) as shipments_may
FROM warehouse.shipments
WHERE arrived_ts >= '2026-05-01' AND arrived_ts < '2026-06-01';

